style.css:
/*
 * This code forces the browser to use a cursive font already
 * installed on your computer, avoiding Google Fonts errors.
 */

/* Target everything with high priority */
* {
    font-family: "Segoe Script", "Zapf Chancery", cursive !important;
}

/* Ensure common text containers are also targeted */
body, html, div, p, span, li, a, input, textarea {
    font-family: "Segoe Script", "Zapf Chancery", cursive !important;
    font-size: 1.1em !important;
}
